sealed class Result {
    data class Success(val data: String) : Result()
    data class Error(val msg: String) : Result()
    object Loading : Result()
}

fun show(r: Result) = when (r) {
    is Result.Success -> "ok ${r.data}"
    is Result.Error -> "err ${r.msg}"
    Result.Loading -> "..."
}

