sealed class Shape {
    data class Circle(val r: Double) : Shape()
    data class Square(val s: Double) : Shape()
}

fun area(sh: Shape): Double = when (sh) {
    is Shape.Circle -> Math.PI * sh.r * sh.r
    is Shape.Square -> sh.s * sh.s
}

fun main() {
    println(area(Shape.Square(3.0)))
}

